describe('Page Title Update on Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should update page title when navigating to different sections', () => {
    cy.title().should('equal', 'Home');

    cy.get('a[href="/about"]').click();
    cy.title().should('equal', 'About');

    cy.get('a[href="/services"]').click();
    cy.title().should('equal', 'Services');

    cy.get('a[href="/contact"]').click();
    cy.title().should('equal', 'Contact');
  });

  it('should update page title when using browser back button', () => {
    cy.title().should('equal', 'Home');

    cy.get('a[href="/about"]').click();
    cy.title().should('equal', 'About');

    cy.go('back');
    cy.title().should('equal', 'Home');

    cy.go('forward');
    cy.title().should('equal', 'About');
  });

  it('should handle rapid navigation and update title correctly', () => {
    cy.get('a[href="/about"]').click();
    cy.get('a[href="/services"]').click();
    cy.get('a[href="/contact"]').click();

    cy.title().should('equal', 'Contact');
  });

  it('should update title when navigating to section with special characters', () => {
    cy.get('a[href="/faq"]').click();
    cy.title().should('equal', 'FAQ - Frequently Asked Questions');
  });

  it('should maintain correct title after page reload', () => {
    cy.get('a[href="/services"]').click();
    cy.title().should('equal', 'Services');

    cy.reload();
    cy.title().should('equal', 'Services');
  });

  it('should update title when navigating from nested section back to root', () => {
    cy.get('a[href="/products"]').click();
    cy.title().should('equal', 'Products');

    cy.get('a[href="/"]').click();
    cy.title().should('equal', 'Home');
  });
});
